#pragma once
#include "kstationStartupTablesTask.h"
#include "kstationNativeMidiPump.h"
namespace kstation {
class NativeStartupTables final {
 using T=StartupTablesTask;using K=T::Kind;using S=T::Stage;
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,1>CodeRanges{{{0x17ba,0x1838}}};bool active()const{return depth_;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){return at>=0x17ba&&at<0x1838;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){K k;if(at==0x17ba)k=K::Both;else if(at==0x17c0)k=K::Delay;else if(at==0x1802)k=K::Samples;else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup tables capacity");jobs_[depth_++]=T{k};}auto&t=jobs_[depth_-1];if(t.awaiting())t.resume();if(at!=boundary(t))throw std::logic_error("Native K startup tables boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(t);FlashCredits cr;cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,int(at+len-1));cr.read=bus(t.stage()==S::ReadRate?0xbf98:0xa812+2*t.index(),2,int(at+len-1));cr.write=bus((t.kind()==K::Delay?0xc59a:0xc622)+4*t.index(),4,c.writeHistory());auto cost=t.nextClocks(cr);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(t,c);
 t.advanceBefore(cost,cr,[&](bool rate,unsigned index){unsigned r=rate?1:4;c.reg16(r)=int16_t(c.read16(int(rate?0xbf98:0xa812+2*index)));if(!rate){c.reg32(1)+=2;c.clockI(2);}val(c,c.reg16(r));return uint16_t(c.reg16(r));},[&](unsigned index,unsigned value){if(uint32_t(c.reg32(t.kind()==K::Delay?5:4))!=value)throw std::logic_error("Native K startup table value differs");c.write32(int32_t(value),int((t.kind()==K::Delay?0xc59a:0xc622)+4*index));val(c,c.reg32(t.kind()==K::Delay?5:4));});
 if(c.cycles-begin!=cost)throw std::logic_error("Native K startup tables clocks differ");if(t.complete())--depth_;else if(!t.awaiting())c.pc=c.makepc(boundary(t));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static unsigned boundary(const T&t){bool d=t.kind()==K::Delay;switch(t.stage()){case S::DelayChild:return 0x17ba;case S::SamplesChild:return 0x17bc;case S::Return:return t.kind()==K::Both?0x17be:d?0x1800:0x1836;case S::BindConstant:return d?0x17c0:0x1802;case S::ReadRate:return d?0x17c6:0x1806;case S::CalculateBase:return d?0x17cc:0x180c;case S::ClearRemainder:return 0x17ce;case S::DoubleBase:return 0x180e;case S::BindSource:return d?0x17d0:0x1810;case S::BindTarget:return d?0x17d6:0x1816;case S::Count:return d?0x17dc:0x181c;case S::ReadCoefficient:return d?0x17de:0x181e;case S::ScaleCoefficient:return (d?0x17e0:0x1820)+2*t.shiftIndex();case S::CopyBase:return 0x17e8;case S::DivideHigh:return 0x17ea;case S::RetainHigh:return 0x17ec;case S::ClearLow:return 0x17ee;case S::DivideLow:return 0x17f0;case S::Merge:return 0x17f2;case S::DoubleResult:return 0x17f4;case S::Write:return d?0x17f6:0x182c;case S::Advance:return d?0x17fa:0x1830;case S::Decrement:return d?0x17fc:0x1832;case S::Repeat:return d?0x17fe:0x1834;case S::MultiplyResult:return 0x182a;default:return 0;}}
 static unsigned bytes(const T&t){switch(t.stage()){case S::BindConstant:return t.kind()==K::Delay?6:4;case S::ReadRate:case S::BindSource:case S::BindTarget:return 6;case S::Write:return 4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static void divide(Stage1Cpu&c){unsigned divisor=uint16_t(c.reg16(4)),v=uint32_t(c.reg32(5));unsigned q=divisor?v/divisor:0;c.ccr=uint8_t((c.ccr&~12)|((divisor&0x8000)?8:0)|(divisor?0:4));c.reg16(5)=int16_t(q);c.reg16(13)=int16_t(v-q*divisor);c.clockI(20);}
 static void shift(Stage1Cpu&c,unsigned r,bool word){unsigned v=word?uint16_t(c.reg16(r)):uint32_t(c.reg32(r));c.ccr=uint8_t((c.ccr&~1)|((v>>(word?15:31))&1));v<<=1;val(c,int32_t(word?v<<16:v));if(word)c.reg16(r)=int16_t(v);else c.reg32(r)=int32_t(v);}
 static void project(const T&t,Stage1Cpu&c){bool d=t.kind()==K::Delay;switch(t.stage()){case S::DelayChild:midi_projection::call(c,0x17c0,0x17bc,false);break;case S::SamplesChild:midi_projection::call(c,0x1802,0x17be,false);break;case S::Return:midi_projection::ret(c);break;case S::BindConstant:if(d)c.reg32(0)=0x3e800000;else c.reg16(0)=int16_t(0x8312);val(c,d?c.reg32(0):c.reg16(0));break;case S::CalculateBase:if(d){unsigned divisor=uint16_t(c.reg16(1)),v=uint32_t(c.reg32(0)),q=divisor?v/divisor:0;c.ccr=uint8_t((c.ccr&~12)|((divisor&0x8000)?8:0)|(divisor?0:4));c.reg16(0)=int16_t(q);c.reg16(8)=int16_t(v-q*divisor);}else c.reg32(0)=int32_t(unsigned(uint16_t(c.reg16(0)))*uint16_t(c.reg16(1)));c.clockI(20);break;case S::ClearRemainder:c.reg16(8)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case S::DoubleBase:shift(c,0,false);break;case S::BindSource:c.reg32(1)=0xa812;val(c,c.reg32(1));break;case S::BindTarget:c.reg32(2)=d?0xc59a:0xc622;val(c,c.reg32(2));break;case S::Count:c.reg8(11)=34;val(c,34);break;case S::ScaleCoefficient:shift(c,4,true);break;case S::CopyBase:c.reg32(5)=c.reg32(0);val(c,c.reg32(5));break;case S::DivideHigh:case S::DivideLow:divide(c);break;case S::RetainHigh:c.reg16(12)=c.reg16(5);val(c,c.reg16(12));break;case S::ClearLow:c.reg16(5)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case S::Merge:c.reg16(13)=c.reg16(12);val(c,c.reg16(13));break;case S::DoubleResult:shift(c,5,false);break;case S::Advance:c.reg32(2)+=4;break;case S::Decrement:{int old=c.reg8(11),v=old-1;val(c,v);if((old&~v)&128)c.ccr|=2;c.reg8(11)=int8_t(v);break;}case S::MultiplyResult:c.reg32(4)=int32_t(unsigned(uint16_t(c.reg16(4)))*uint16_t(c.reg16(8)));c.clockI(20);break;default:break;}}
 std::array<T,4>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
}
